import { mapLayers, renderMapShell } from './MapShell';

describe('mapLayers', () => {
  it('should be an array of layer objects with required properties', () => {
    expect(Array.isArray(mapLayers)).toBe(true);
    mapLayers.forEach(layer => {
      expect(layer).toHaveProperty('id');
      expect(typeof layer.id).toBe('string');
      expect(layer).toHaveProperty('name');
      expect(typeof layer.name).toBe('string');
      expect(layer).toHaveProperty('description');
      expect(typeof layer.description).toBe('string');
      expect(layer).toHaveProperty('defaultEnabled');
      expect(typeof layer.defaultEnabled).toBe('boolean');
    });
  });

  it('should have unique layer ids', () => {
    const ids = mapLayers.map(l => l.id);
    const uniqueIds = new Set(ids);
    expect(uniqueIds.size).toBe(ids.length);
  });

  it('should have at least one layer with defaultEnabled true', () => {
    expect(mapLayers.some(l => l.defaultEnabled)).toBe(true);
  });

  it('should have at least one layer with defaultEnabled false', () => {
    expect(mapLayers.some(l => !l.defaultEnabled)).toBe(true);
  });
});

describe('renderMapShell', () => {
  let html: string;

  beforeEach(() => {
    html = renderMapShell();
  });

  it('should return a string of HTML', () => {
    expect(typeof html).toBe('string');
    expect(html.length).toBeGreaterThan(0);
  });

  it('should include the main workspace structure', () => {
    expect(html).toContain('<main class="workspace">');
    expect(html).toContain('<aside class="sidebar panel"');
    expect(html).toContain('<section class="map-panel panel"');
    expect(html).toContain('<div id="map" class="map-canvas" role="presentation"></div>');
  });

  it('should render all mapLayers as list items with correct ids and names', () => {
    mapLayers.forEach(layer => {
      expect(html).toContain(`<li class="layer-list__item">`);
      expect(html).toContain(`id="layer-${layer.id}"`);
      expect(html).toContain(`data-layer-id="${layer.id}"`);
      expect(html).toContain(`<span class="layer-toggle__title">${layer.name}</span>`);
      expect(html).toContain(`<span class="layer-toggle__description" data-layer-description-id="${layer.id}">`);
      expect(html).toContain(layer.description);
    });
  });

  it('should check the input for layers with defaultEnabled true', () => {
    mapLayers.forEach(layer => {
      const inputTag = new RegExp(
        `<input\\s+[^>]*id="layer-${layer.id}"[^>]*${layer.defaultEnabled ? 'checked' : ''}[^>]*>`,
        'i'
      );
      expect(html).toMatch(inputTag);
    });
  });

  it('should add the city-limits badge only to the city-limits layer', () => {
    const cityLimitsBadge = /<label class="layer-toggle layer-toggle--city-limits"[^>]*>[\s\S]*<span class="layer-toggle__badge">contorno<\/span>/;
    expect(html).toMatch(cityLimitsBadge);

    mapLayers
      .filter(l => l.id !== 'city-limits')
      .forEach(layer => {
        const badgePattern = new RegExp(
          `<label class="layer-toggle(?! layer-toggle--city-limits)"[^>]*>[^<]*<span class="layer-toggle__badge">contorno<\\/span>`,
          'i'
        );
        expect(html).not.toMatch(badgePattern);
      });
  });

  it('should include the description visibility toggle', () => {
    expect(html).toContain('id="toggle-layer-descriptions"');
    expect(html).toContain('data-description-visibility-toggle');
    expect(html).toContain('Show layer descriptions');
  });

  it('should include the map panel header and action button', () => {
    expect(html).toContain('<div class="map-panel__header">');
    expect(html).toContain('aria-label="Center map on Pátio do Colégio"');
    expect(html).toContain('title="Center map on Pátio do Colégio"');
    expect(html).toContain('<svg');
  });

  it('should handle edge case: no duplicate input ids', () => {
    const matches = html.match(/id="layer-([a-zA-Z0-9-_]+)"/g) || [];
    const ids = matches.map(m => m.replace(/id="layer-/, '').replace(/"/, ''));
    const uniqueIds = new Set(ids);
    expect(uniqueIds.size).toBe(ids.length);
  });

  it('should not render any unexpected or missing layers', () => {
    // Check that only known layer ids are present
    const allIds = mapLayers.map(l => l.id);
    const htmlIds = Array.from(html.matchAll(/id="layer-([a-zA-Z0-9-_]+)"/g)).map(m => m[1]);
    htmlIds.forEach(id => {
      expect(allIds).toContain(id);
    });
    expect(htmlIds.length).toBe(mapLayers.length);
  });

  it('should render the correct number of layer list items', () => {
    const liCount = (html.match(/<li class="layer-list__item">/g) || []).length;
    expect(liCount).toBe(mapLayers.length);
  });

  it('should not throw or fail when called multiple times', () => {
    expect(() => renderMapShell()).not.toThrow();
    expect(() => renderMapShell()).not.toThrow();
  });
});
