jest.mock('./app', () => ({
  renderApp: jest.fn(() => '<div>App Content</div>')
}));
jest.mock('./map', () => ({
  mountMap: jest.fn()
}));
jest.mock('leaflet/dist/leaflet.css', () => {});
jest.mock('./styles/main.css', () => {});

describe('src/main.ts', () => {
  let originalQuerySelector: typeof document.querySelector;

  beforeEach(() => {
    jest.resetModules();
    document.body.innerHTML = '';
    originalQuerySelector = document.querySelector;
  });

  afterEach(() => {
    document.querySelector = originalQuerySelector;
    jest.clearAllMocks();
  });

  it('should render the app and mount the map when #app exists', () => {
    const rootDiv = document.createElement('div');
    rootDiv.id = 'app';
    document.body.appendChild(rootDiv);

    // Re-require to run the module code
    require('./main');

    const { renderApp } = require('./app');
    const { mountMap } = require('./map');

    expect(renderApp).toHaveBeenCalled();
    expect(rootDiv.innerHTML).toBe('<div>App Content</div>');
    expect(mountMap).toHaveBeenCalledWith(rootDiv);
  });

  it('should throw an error if #app does not exist', () => {
    expect(() => {
      require('./main');
    }).toThrowError('App root element "#app" was not found.');
  });

  it('should not call mountMap or renderApp if #app does not exist', () => {
    try {
      require('./main');
    } catch (e) {
      // expected
    }
    const { renderApp } = require('./app');
    const { mountMap } = require('./map');
    expect(renderApp).not.toHaveBeenCalled();
    expect(mountMap).not.toHaveBeenCalled();
  });

  it('should work if #app is not a div but another element', () => {
    const rootSpan = document.createElement('span');
    rootSpan.id = 'app';
    document.body.appendChild(rootSpan);

    require('./main');

    const { renderApp } = require('./app');
    const { mountMap } = require('./map');

    expect(renderApp).toHaveBeenCalled();
    expect(rootSpan.innerHTML).toBe('<div>App Content</div>');
    expect(mountMap).toHaveBeenCalledWith(rootSpan);
  });
});
