describe('getPublicAssetPath', () => {
  const originalImportMeta = globalThis.import?.meta;

  beforeEach(() => {
    // @ts-ignore
    globalThis.import = {
      meta: {
        env: {
          BASE_URL: '/base/',
        },
      },
    };
  });

  afterEach(() => {
    // @ts-ignore
    if (originalImportMeta) {
      globalThis.import = { meta: originalImportMeta };
    } else {
      // @ts-ignore
      delete globalThis.import;
    }
  });

  it('returns correct path when assetPath does not start with a slash', () => {
    expect(getPublicAssetPath('img/logo.png')).toBe('/base/img/logo.png');
  });

  it('removes a single leading slash from assetPath', () => {
    expect(getPublicAssetPath('/img/logo.png')).toBe('/base/img/logo.png');
  });

  it('removes multiple leading slashes from assetPath', () => {
    expect(getPublicAssetPath('///img/logo.png')).toBe('/base/img/logo.png');
  });

  it('handles empty assetPath', () => {
    expect(getPublicAssetPath('')).toBe('/base/');
  });

  it('handles assetPath with only slashes', () => {
    expect(getPublicAssetPath('/////')).toBe('/base/');
  });

  it('handles BASE_URL without trailing slash', () => {
    // @ts-ignore
    globalThis.import.meta.env.BASE_URL = '/static';
    expect(getPublicAssetPath('img/logo.png')).toBe('/staticimg/logo.png');
  });

  it('handles BASE_URL as empty string', () => {
    // @ts-ignore
    globalThis.import.meta.env.BASE_URL = '';
    expect(getPublicAssetPath('img/logo.png')).toBe('img/logo.png');
  });

  it('throws if import.meta.env.BASE_URL is undefined', () => {
    // @ts-ignore
    globalThis.import.meta.env.BASE_URL = undefined;
    expect(() => getPublicAssetPath('img/logo.png')).toThrow();
  });

  it('throws if import.meta.env is undefined', () => {
    // @ts-ignore
    globalThis.import.meta.env = undefined;
    expect(() => getPublicAssetPath('img/logo.png')).toThrow();
  });

  it('throws if import.meta is undefined', () => {
    // @ts-ignore
    globalThis.import.meta = undefined;
    expect(() => getPublicAssetPath('img/logo.png')).toThrow();
  });
});
