import * as mapModule from '../src/map';

describe('map.ts utility functions', () => {
  describe('getDirectChildText', () => {
    it('returns trimmed text content of direct child with matching localName', () => {
      const parent = document.createElement('parent');
      const child = document.createElement('foo');
      child.textContent = '  bar  ';
      parent.appendChild(child);
      expect(mapModule.getDirectChildText(parent, 'foo')).toBe('bar');
    });

    it('returns null if no matching child', () => {
      const parent = document.createElement('parent');
      expect(mapModule.getDirectChildText(parent, 'missing')).toBeNull();
    });

    it('returns null if child has no textContent', () => {
      const parent = document.createElement('parent');
      const child = document.createElement('foo');
      parent.appendChild(child);
      expect(mapModule.getDirectChildText(parent, 'foo')).toBeNull();
    });
  });

  describe('getDirectChildElement', () => {
    it('returns direct child element with matching localName', () => {
      const parent = document.createElement('parent');
      const child = document.createElement('bar');
      parent.appendChild(child);
      expect(mapModule.getDirectChildElement(parent, 'bar')).toBe(child);
    });

    it('returns null if no matching child', () => {
      const parent = document.createElement('parent');
      expect(mapModule.getDirectChildElement(parent, 'baz')).toBeNull();
    });
  });

