        `<root>
          <Layer id="1"></Layer>
          <Layer id="2"></Layer>
          <Other></Other>
        </root>`,
        'application/xml'
      );
      const layers = mapModule.getLayerElements(xml);
      expect(layers).toHaveLength(2);
      expect(layers[0].getAttribute('id')).toBe('1');
      expect(layers[1].getAttribute('id')).toBe('2');
